#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ── Helpers of this wizard ─────────────────────────────────────────────────
REMOTE_URL_DEFAULT="git@github.com:FYGS/fygs.dev.git"
BACKUP_DIR="${BACKUP_DIR:-$HOME/fygs-dev-backups}"
WORK_DIR="${WORK_DIR:-$(mktemp -d)}"
PURGE_PATHS=(.env .env.production .env.local .env.test .env.development)

# pip --user installs scripts in a directory that is rarely on PATH (notably on Windows): add it for this run
_user_scripts="$(python -c "import sysconfig,os;print(sysconfig.get_path('scripts', 'nt_user' if os.name == 'nt' else 'posix_user'))" 2>/dev/null | tr -d '
' || true)"
[[ -n "$_user_scripts" ]] && PATH="$(cygpath -u "$_user_scripts" 2>/dev/null || printf %s "$_user_scripts"):$PATH"

has_filter_repo() { git filter-repo --version >/dev/null 2>&1; }

run_wizard() {

TOTAL_STAGES=8
ENV_FILE="${WIZARD_ENV_FILE:-$HOME/.config/fygs-dev/purge.env}"   # the library defaults to ./.env: never write secrets there
mkdir -p "$(dirname "$ENV_FILE")"

banner "fygs.dev: remove .env files from the whole git history (issue #40)"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Before anything: the secrets must already be dead"
say "This rewrites every commit hash (about 500) and force-pushes every branch and tag."
say "It removes: ${PURGE_PATHS[*]}"
say ""
warn "Run it only AFTER scripts/ops/rotate-secrets.sh finished (old secrets revoked and checked)."
warn "Freeze the repository first: no other session, clone or CI may push or merge until stage 5 is done."
warn "Rotation is what protects you. This purge only tidies the history."
warn "Pull requests keep their old commits at GitHub (refs/pull/*): stage 7 asks GitHub Support to clean those."
say ""
confirm "Have the exposed secrets been rotated and revoked?" || { say "Run the rotation first. Nothing was changed."; exit 0; }

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Tools"
command -v git >/dev/null 2>&1 || { warn "git is missing"; exit 1; }
if has_filter_repo; then
  say "${GREEN}✓${RESET} git filter-repo is installed"
else
  warn "git filter-repo is not installed"
  say "Install it with:  python -m pip install --user git-filter-repo"
  say "(then make sure the pip scripts directory is on your PATH, and re-run this wizard)"
  exit 1
fi
ask REMOTE_URL "Remote to rewrite (Enter keeps the default):"
REMOTE_URL="${REMOTE_URL:-$REMOTE_URL_DEFAULT}"
write_env REMOTE_URL "$REMOTE_URL"
pause

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Back up the repository as it is now"
mkdir -p "$BACKUP_DIR"
BACKUP="$BACKUP_DIR/fygs.dev-$(date +%Y%m%d-%H%M%S).git"
say "A full mirror goes to: $BACKUP"
warn "This backup still contains the dead secrets: keep it private and delete it once you are sure (stage 8)."
confirm "Create the backup?" || { say "No backup, no rewrite. Stopped."; exit 0; }
git clone --mirror "$REMOTE_URL" "$BACKUP"
say "${GREEN}✓${RESET} backup done ($(git -C "$BACKUP" rev-list --all --count) commits)"
pause

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Rewrite a working copy (nothing is pushed yet)"
WORK="$WORK_DIR/fygs.dev-rewrite.git"
HEADS_BEFORE="$(git ls-remote --heads "$REMOTE_URL" | sort)"   # what the remote looked like when the rewrite started
git clone --mirror "$REMOTE_URL" "$WORK"
before=$(git -C "$WORK" rev-list --all --count)
args=(--invert-paths --force)
for p in "${PURGE_PATHS[@]}"; do args+=(--path "$p"); done
( cd "$WORK" && git filter-repo "${args[@]}" )
after=$(git -C "$WORK" rev-list --all --count)
say "commits before: $before, after: $after (commits that only touched these files disappear)"
left=$(git -C "$WORK" log --all --oneline -- "${PURGE_PATHS[@]}" | wc -l | tr -d ' ')
if [[ "$left" == "0" ]]; then
  say "${GREEN}✓${RESET} no commit touches ${PURGE_PATHS[*]} any more"
else
  warn "$left commit(s) still touch those files: stop here, nothing was pushed"; exit 1
fi
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Force-push the rewritten history"
say "Branches that will be rewritten:"
git -C "$WORK" for-each-ref --format='    %(refname:short)' refs/heads | head -40
say ""
warn "This replaces the history on GitHub. Anyone with a clone must re-clone. Coolify clones fresh at each build: unaffected."
warn "Open pull requests will show a different base. Your local clones and worktrees of this repository become unusable."
confirm "Force-push every branch and tag of $REMOTE_URL?" || { say "Stopped. Nothing was pushed. The backup is at $BACKUP"; exit 0; }
confirm "Last chance: really overwrite the remote history?" || { say "Stopped."; exit 0; }
# Anyone who pushed since the clone would be silently overwritten: refuse if the remote moved
if [[ "$(git ls-remote --heads "$REMOTE_URL" | sort)" != "$HEADS_BEFORE" ]]; then
  warn "A branch changed on the remote since the rewrite started (someone pushed or merged). Nothing was pushed: re-run from stage 3."
  exit 1
fi
git -C "$WORK" remote add origin "$REMOTE_URL" 2>/dev/null || git -C "$WORK" remote set-url origin "$REMOTE_URL"
git -C "$WORK" push --force --all origin
git -C "$WORK" push --force --tags origin
say "${GREEN}✓${RESET} pushed"
pause

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Your local clones"
say "Their history no longer matches GitHub. For each local clone and worktree of fygs.dev:"
step "Do NOT merge or pull (that would bring the old history back and expose it again)."
step "Delete the folder and clone again:  git clone $REMOTE_URL"
step "Re-create your worktrees from the fresh clone."
step "If a branch only exists locally, copy its files elsewhere first, then re-apply them on the new history."
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "GitHub still caches the old commits"
say "Commits stay reachable by hash and through pull-request refs until GitHub runs a garbage collection."
open_url "https://support.github.com/contact"
step "Choose the repository content / removing sensitive data topic and say: 'FYGS/fygs.dev: history rewritten to remove .env files;"
step "please run garbage collection and remove cached views and the pull-request refs that still reference the old commits'."
note "The values were rotated first, so the urgency is low; do it anyway."
pause

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Verify and clean up"
say "From a fresh clone:"
step "git log --all -- .env .env.production    (must print nothing)"
step "Open the repository on github.com, Settings → Security: enable secret scanning and push protection (issue #47)."
say ""
say "The backup of the OLD history is at: $BACKUP"
say "The rewrite working copy is at: $WORK"
warn "Both contain the dead secrets. After a week without problems, delete them:  rm -rf '$BACKUP' '$WORK'"
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
